import { createContext, useContext, useState, useCallback } from 'react';

const AppContext = createContext(null);

export function AppProvider({ children }) {
  const [user, setUser] = useState(null);
  const [hobbies, setHobbies] = useState([]);
  const [posts, setPosts] = useState([]);
  const [postsLoaded, setPostsLoaded] = useState(false);

  const login = useCallback((username) => {
    setUser(username);
  }, []);

  const signup = useCallback((username) => {
    setUser(username);
  }, []);

  const selectHobbies = useCallback((selected) => {
    setHobbies(selected);
  }, []);

  const vote = useCallback((postId, direction) => {
    setPosts((prev) =>
      prev.map((p) => {
        if (p.id !== postId) return p;
        let upvotes = p.upvotes;
        let userVote = p.userVote;
        if (direction === 'up') {
          if (userVote === 'up') {
            upvotes -= 1;
            userVote = null;
          } else if (userVote === 'down') {
            upvotes += 2;
            userVote = 'up';
          } else {
            upvotes += 1;
            userVote = 'up';
          }
        } else {
          if (userVote === 'down') {
            upvotes += 1;
            userVote = null;
          } else if (userVote === 'up') {
            upvotes -= 2;
            userVote = 'down';
          } else {
            upvotes -= 1;
            userVote = 'down';
          }
        }
        return { ...p, upvotes, userVote };
      })
    );
  }, []);

  const addComment = useCallback((postId, text, author) => {
    setPosts((prev) =>
      prev.map((p) => {
        if (p.id !== postId) return p;
        const newComment = {
          id: `c${Date.now()}`,
          author,
          text,
          time: 'just now',
          upvotes: 0,
        };
        return { ...p, comments: [...p.comments, newComment] };
      })
    );
  }, []);

  const value = {
    user,
    hobbies,
    posts,
    postsLoaded,
    login,
    signup,
    selectHobbies,
    vote,
    addComment,
    setPosts,
    setPostsLoaded,
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
}

export function useApp() {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp must be used within AppProvider');
  return ctx;
}
